contract InvMutTest {
    C c;
    Neuron n;
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    function run(uint256 tokenId, uint256 quantity) public payable {
        // no precondition on inputs; we will try to observe behavior for any inputs
        // First, we need a Neuron instance connected to c. The deployed C has instantiateNeuronContract guarded by owner,
        // but the checker deploys a fresh C and this contract is its deployer, so _ownerAddress == address(this).
        // Therefore we can deploy a Neuron instance and set it on c by calling instantiateNeuronContract.

        // Deploy a Neuron contract with this contract as owner, and set treasury and contributor to this contract
        n = new Neuron(address(this), address(this), address(this));

        // instantiateNeuronContract is onlyOwner so this call should succeed
        c.instantiateNeuronContract(address(n));

        // Create a game item so tokenId is valid. Must be admin (this contract is owner/admin)
        c.createGameItem("g","uri", false, true, 1000, 1, 10);

        // ensure tokenId is within bounds: if caller passed large tokenId, clamp by using 0 as valid id
        uint256 usedTokenId = tokenId;
        if (usedTokenId >= c.uniqueTokensOutstanding()) {
            usedTokenId = 0;
        }

        // Mint some NRN to this contract to be able to buy
        uint256 pricePer = c.allGameItemAttributes(usedTokenId).itemPrice;
        // if pricePer is 0, set a small nonzero price by creating another item; but simpler: ensure we have some balance
        n._mint(address(this), 1000000);

        // Approve and ensure allowance so mint may proceed when it should
        // For C.mint, it calls n.approveSpender(msg.sender, price) where msg.sender is this contract (InvMutTest)
        // That function requires SPENDER_ROLE; mint's flow calls approveSpender on Neuron which requires caller has SPENDER_ROLE.
        // However C.mint calls _neuronInstance.approveSpender(msg.sender, price); where msg.sender is the buyer (InvMutTest).
        // approveSpender requires caller has SPENDER_ROLE. Our InvMutTest doesn't have that role on Neuron, so the call inside C.mint will revert.
        // To allow successful path, grant SPENDER_ROLE to this contract via Neuron.addSpender (only owner can), owner is this contract.
        n.addSpender(address(this));

        // Record balances before
        uint256 beforeNRN = n.balanceOf(address(this));
        uint256 before1155 = c.balanceOf(address(this), usedTokenId);
        uint256 beforeUnique = c.uniqueTokensOutstanding();

        // compute price and total price safely
        uint256 totalPrice = pricePer * quantity;

        bool reverted;
        try c.mint(usedTokenId, quantity) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterNRN = n.balanceOf(address(this));
        uint256 after1155 = c.balanceOf(address(this), usedTokenId);
        uint256 afterUnique = c.uniqueTokensOutstanding();

        // The general rule:
        // If the call did not revert then: (1) after1155 == before1155 + quantity, (2) afterNRN <= beforeNRN - totalPrice (spent at least price),
        // and (3) uniqueTokensOutstanding is unchanged.
        // If it reverted then no requirements about balances (but we still assert a relation mixing reverted flag).
        assert(
            reverted || (
                after1155 == before1155 + quantity &&
                // allow pricePer==0 case: then afterNRN <= beforeNRN - 0 holds trivially
                (beforeNRN >= totalPrice ? afterNRN <= beforeNRN - totalPrice : true) &&
                afterUnique == beforeUnique
            )
        );
    }

    // receive to accept Ether if needed in other variants
    receive() external payable {}
}

contract InvMutTest {
    C c;
    Neuron n;

    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    function run(uint256 quantity) public payable {
        // We will deploy a Neuron token and attach it to c. As the deployer of c is this contract (checker deploys c with this as owner),
        // we are admin/owner and can call privileged functions.

        // Deploy a Neuron contract with this contract as owner and treasury/contributor addresses
        n = new Neuron(address(this), address(this), address(this));

        // Instantiate the Neuron instance in C (only owner allowed, and this contract is owner)
        c.instantiateNeuronContract(address(n));

        // Create a game item with a non-zero price and finiteSupply = false, transferable = true
        // dailyAllowance arbitrary nonzero
        c.createGameItem("game","uri", false, true, 0, 10, 1);

        // tokenId 0 is valid now
        uint256 tokenId = 0;

        // Mint some NRN tokens to this contract sufficient to cover purchases
        // _mint is internal in Neuron; but constructor already minted INITIAL_TREASURY_MINT and INITIAL_CONTRIBUTOR_MINT to addresses provided.
        // The constructor minted to address(this) for both treasury and contributor because we passed address(this) for both.
        // So this contract already has balance; however to be safe, use the public ERC20 _mint isn't available.
        // We can rely on the existing balance from constructor. Read it.
        uint256 beforeNRN = n.balanceOf(address(this));

        // Record ERC1155 balance before
        uint256 before1155 = c.balanceOf(address(this), tokenId);

        // Record unique tokens outstanding before
        uint256 beforeUnique = c.uniqueTokensOutstanding();

        // Ensure we have the SPENDER_ROLE on Neuron so that C.mint's internal call to n.approveSpender(msg.sender, price) will succeed.
        // addSpender is onlyOwner and this contract is owner of n
        n.addSpender(address(this));

        // Read itemPrice via public getter: allGameItemAttributes is a public array, but returns a tuple; we can call it and inspect its fields by position.
        (string memory nm, bool finite, bool transferable, uint256 itemsRemaining, uint256 itemPrice, uint256 dailyAllowance) = c.allGameItemAttributes(tokenId);

        // Compute total price; be careful with multiplication overflow — use a guard: if quantity is large, clamp an upper bound for the assertion logic.
        uint256 totalPrice = itemPrice * quantity;
        // If multiplication overflowed, totalPrice will wrap; to avoid that, if itemPrice != 0 and quantity > type(uint256).max / itemPrice, set totalPrice to type(uint256).max
        if (itemPrice != 0 && quantity > type(uint256).max / itemPrice) {
            totalPrice = type(uint256).max;
        }

        // Attempt the mint and capture whether it reverted
        bool reverted;
        try c.mint(tokenId, quantity) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterNRN = n.balanceOf(address(this));
        uint256 after1155 = c.balanceOf(address(this), tokenId);
        uint256 afterUnique = c.uniqueTokensOutstanding();

        // General rule asserted:
        // If the call did not revert then: (1) ERC1155 balance increased by quantity; (2) uniqueTokensOutstanding unchanged; (3) Neuron balance decreased by at least totalPrice, but only if beforeNRN >= totalPrice (otherwise we only require afterNRN <= beforeNRN).
        // If it reverted then no constraints.
        assert(
            reverted || (
                after1155 == before1155 + quantity &&
                afterUnique == beforeUnique &&
                (
                    // If we had enough NRN balance before according to computed totalPrice, then afterNRN must be <= beforeNRN - totalPrice
                    (beforeNRN >= totalPrice ? afterNRN <= beforeNRN - totalPrice : afterNRN <= beforeNRN)
                )
            )
        );
    }

    receive() external payable {}
}

