contract InvMutTest {
    C c;
    Neuron n;

    constructor(C _c) {
        c = _c;
    }

    // single public entry performing the property test
    function run(address neuronAddress, address to, uint256 amount) public payable {
        require(neuronAddress != address(0) && to != address(0));

        // instantiate Neuron interface via its deployed address
        n = Neuron(neuronAddress);

        // read total supply before
        uint256 beforeTotal = n.totalSupply();

        // try to mint from this contract (which likely does NOT have MINTER_ROLE initially)
        bool revertedNoRole;
        try n.mint(to, amount) {
            revertedNoRole = false;
        } catch {
            revertedNoRole = true;
        }

        // Now, if this contract has MINTER_ROLE, mint should have succeeded and increased supply by amount
        // We can observe hasRole(MINTER_ROLE, address(this)) via public hasRole
        bytes32 MINTER_ROLE = keccak256("MINTER_ROLE");
        bool has = n.hasRole(MINTER_ROLE, address(this));

        uint256 afterTotal = n.totalSupply();

        // General property:
        // - If caller does NOT have MINTER_ROLE then the mint attempt must revert (revertedNoRole == true).
        // - If caller DOES have MINTER_ROLE then the mint attempt must not revert and totalSupply increased by amount (afterTotal == beforeTotal + amount), and still less than MAX_SUPPLY.
        // We express both in one assertion using readable logic.
        assert((!has && revertedNoRole) || (has && !revertedNoRole && afterTotal == beforeTotal + amount && afterTotal < n.MAX_SUPPLY()));
    }

    receive() external payable {}
 }

