contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that runs the property test
    function run(address admin, string calldata name_, string calldata tokenURI, bool finiteSupply, bool transferable, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance) public payable {
        // require that the provided admin is not the zero address so admin operations may be meaningful
        require(admin != address(0));

        // Make sure this contract is recognized as admin by setting ownership to this contract via transferOwnership
        // The newly deployed C has an owner set at construction; only that owner can call transferOwnership.
        // We cannot assume who that is, so we attempt to transfer ownership by calling transferOwnership on c from this contract.
        // This will succeed only if this contract is the current owner; if it reverts, we catch that and proceed — the property must still hold when createGameItem is callable.

        bool transferOwnershipSucceeded;
        try c.transferOwnership(address(this)) {
            transferOwnershipSucceeded = true;
        } catch {
            transferOwnershipSucceeded = false;
        }

        // If transferOwnershipSucceeded is true, this contract is now owner and can adjust admin access for `admin`.
        if (transferOwnershipSucceeded) {
            // give admin access to the provided admin address so they can call createGameItem
            c.adjustAdminAccess(admin, true);
        } else {
            // else attempt to make this contract an admin by calling adjustAdminAccess from admin address is impossible here.
            // Instead, we try to make this contract an admin by calling adjustAdminAccess with our own address via a call that may revert.
            // This is best-effort: if it fails, later createGameItem from admin will fail and the property will account for that.
            try c.adjustAdminAccess(address(this), true) {
                // ok
            } catch {
                // ignore
            }
        }

        // Read uniqueTokensOutstanding before the creation attempt
        uint256 beforeCount = c.uniqueTokensOutstanding();

        // Prepare to call createGameItem from the provided admin address by performing a low-level call with encoded calldata.
        // We must send the call as msg.sender == admin. To do so from this contract, use address(c).call with encoded function and use delegate? Not allowed.
        // Instead, we require that admin be this contract so we can call c.createGameItem directly (since only this contract can set itself as admin above in some branches).
        // To keep the test general, if admin != address(this), we attempt to make admin == address(this) by giving admin access to this contract earlier; otherwise the call will revert.

        bool didRevert;
        // Call createGameItem from this contract (msg.sender == address(this)). It will succeed only if isAdmin[this] is true.
        try c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint256 afterCount = c.uniqueTokensOutstanding();

        // If the create call did not revert, then we expect afterCount == beforeCount + 1 and the uri for the new token id (beforeCount) equals tokenURI when tokenURI is non-empty, otherwise it may fall back to base URI.
        // If the call reverted, we assert that counts didn't increase.

        if (!didRevert) {
            // must have increased by exactly 1
            assert(afterCount == beforeCount + 1);
            // the newly created tokenId is beforeCount
            string memory returnedURI = c.uri(beforeCount);
            // If the provided tokenURI was non-empty, the contract sets it via setTokenURI; expect equality.
            bool providedNonEmpty = bytes(tokenURI).length > 0;
            if (providedNonEmpty) {
                assert(keccak256(bytes(returnedURI)) == keccak256(bytes(tokenURI)));
            } else {
                // if provided empty, returnedURI should be either super.uri or empty; enforce non-breaking relation: returnedURI length >= 0
                assert(bytes(returnedURI).length >= 0);
            }
        } else {
            // if reverted, the unique tokens count must be unchanged
            assert(afterCount == beforeCount);
        }
    }

    receive() external payable {}
}

