        uint256 beforeCount = c.uniqueTokensOutstanding();

        // perform the state-changing call and capture whether it reverted
        bool didRevert;
        try c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // read after values
        uint256 afterCount = c.uniqueTokensOutstanding();
        string memory returnedURI = "";
        // only call view when the token id potentially exists to avoid reverting; if afterCount > 0 and !didRevert and afterCount == beforeCount + 1 then newId = beforeCount
        if (!didRevert && afterCount == beforeCount + 1) {
            returnedURI = c.uri(beforeCount);
        }

        // Single general assertion: either the call reverted and count unchanged, or it succeeded and count incremented by 1 and when a non-empty tokenURI was provided it matches the stored uri for the new token id.
        assert( (didRevert && afterCount == beforeCount) || (!didRevert && afterCount == beforeCount + 1 && (bytes(tokenURI).length == 0 || keccak256(bytes(returnedURI)) == keccak256(bytes(tokenURI)))) );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Only admins can call createGameItem; ensure caller is admin by using contract that deployed c (checker deploys c with this contract as deployer)
    function run(string calldata name_, string calldata tokenURI, bool finiteSupply, bool transferable, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance) public payable {
        // require parameter sizes small to help analysis
        require(bytes(name_).length <= 64);
        require(bytes(tokenURI).length <= 128);
        // record count before
        uint256 before = c.uniqueTokensOutstanding();

        // try the call and record if it reverted
        bool reverted;
        try c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = c.uniqueTokensOutstanding();

        // Assert general rule: either reverted and count unchanged, or succeeded and count increased by exactly 1
        assert((reverted && after == before) || (!reverted && after == before + 1));
    }

    receive() external payable {}
}

