    constructor(C _c) { c = _c; }

    // single public function with inputs driving a purchase flow
    function run(address neuronAddress, address buyer, uint256 tokenId, uint256 quantity) public payable {
        // instantiate neuron interface in test to observe Neuron public state
        n = Neuron(neuronAddress);

        // Preconditions: tokenId must be an existing token index
        uint256 totalTokens = c.uniqueTokensOutstanding();
