        require(tokenId < totalTokens);

        // read important before-values
        uint256 beforeBuyerBalance = c.balanceOf(buyer, tokenId);
        uint256 beforeTreasuryNrn = n.balanceOf(c.treasuryAddress());
        uint256 itemPrice = c.allGameItemAttributes(tokenId).itemPrice; // public array accessor

        // compute expected price and require no overflow
        uint256 price = itemPrice * quantity;
        require(itemPrice == 0 || price / itemPrice == quantity);

        // Track allowance remaining and replenish time for buyer before call
        uint256 beforeAllowanceRemaining = c.allowanceRemaining(buyer, tokenId);
        uint256 beforeReplenishTime = c.dailyAllowanceReplenishTime(buyer, tokenId);
        uint256 dailyAllowance = c.allGameItemAttributes(tokenId).dailyAllowance;

        // Attempt the mint call and record whether it reverted
        bool reverted = false;
        try c.mint(tokenId, quantity) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After-values
        uint256 afterBuyerBalance = c.balanceOf(buyer, tokenId);
        uint256 afterTreasuryNrn = n.balanceOf(c.treasuryAddress());
        uint256 afterAllowanceRemaining = c.allowanceRemaining(buyer, tokenId);
        uint256 afterReplenishTime = c.dailyAllowanceReplenishTime(buyer, tokenId);

        // General rule:
        // If mint succeeded then: buyer token balance increased by quantity,
        // treasury NRN decreased by price, and allowanceRemaining decreased by quantity
        // (taking into account that if the daily allowance was expired it gets replenished
        // to dailyAllowance before subtracting quantity).
        bool allowanceWasReplenished = (beforeReplenishTime <= block.timestamp) && (afterReplenishTime > beforeReplenishTime);
        uint256 expectedBeforeAllowance = beforeAllowanceRemaining;
        if (beforeReplenishTime <= block.timestamp) {
            expectedBeforeAllowance = dailyAllowance;
        }

        assert(
            reverted || (
                afterBuyerBalance == beforeBuyerBalance + quantity
                && beforeTreasuryNrn >= price
                && afterTreasuryNrn + price == beforeTreasuryNrn
                && afterAllowanceRemaining == expectedBeforeAllowance - quantity
            )
        );
    }

    // fallback/receive not needed but allow receiving Ether
    receive() external payable {}
}

